/* r = the comb multiplication of the 64 radix-16 digits of a scalar below 2^255, recoded on the
   way with s2n-bignum's bias: nibble i plus the bias, bias' = (nibble + bias >= 9), digit =
   nibble + bias - 16 bias' in [-7, 8]. Digit i against table[i], which holds [1..8][16^i]B as
   twelve-word affine entries (Y+X, Y-X, 2dT): every entry read and the one of index |d| - 1
   kept by word masks (d = 0 keeps the identity), a negative digit's Y+X and Y-X swapped and
   its 2dT taken as 2p - 2dT, then the affine addition. Constant time. */
static inline void
fd_ge_ref_comb( ulong r[16], ulong const table[64][8][12], uchar const scalar[32] ) {
  ulong acc[16] = { 0UL, 0UL, 0UL, 0UL, 1UL, 0UL, 0UL, 0UL, 1UL, 0UL, 0UL, 0UL, 0UL, 0UL, 0UL, 0UL };
  ulong bias = 0UL;
  for( int i=0; i<64; i++ ) {
    ulong bf = ((ulong)(scalar[i>>1] >> (4*(i&1))) & 15UL) + bias;
    bias = (bf + 7UL) >> 4;  /* bf >= 9 */
    ulong d = bf - (bias << 4);
    ulong sg = d >> 63, ms = 0UL - sg;
    ulong ix = (d ^ ms) + sg - 1UL;  /* |d| - 1; all ones for d = 0 */
    ulong p[4] = { 1UL, 0UL, 0UL, 0UL }, m[4] = { 1UL, 0UL, 0UL, 0UL }, k[4] = { 0UL, 0UL, 0UL, 0UL };
    for( int e=0; e<8; e++ ) {
      ulong x = ix ^ (ulong)e;
      ulong eq = ((x | (0UL - x)) >> 63) - 1UL;  /* all ones when ix == e */
      for( int j=0; j<4; j++ ) {
        p[j] ^= (p[j] ^ table[i][e][j])   & eq;
        m[j] ^= (m[j] ^ table[i][e][4+j]) & eq;
        k[j] ^= (k[j] ^ table[i][e][8+j]) & eq;
      }
    }
    ulong ent[12], n[4], c;
    c = fd_fe64_subb( 18446744073709551578UL, k[0], &n[0] );
    c = fd_fe64_sbb( 18446744073709551615UL, k[1], c, &n[1] );
    c = fd_fe64_sbb( 18446744073709551615UL, k[2], c, &n[2] );
    n[3] = 18446744073709551615UL - k[3] - c;
    for( int j=0; j<4; j++ ) {
      ulong sw = (p[j] ^ m[j]) & ms;
      ent[j] = p[j] ^ sw; ent[4+j] = m[j] ^ sw; ent[8+j] = k[j] ^ ((k[j] ^ n[j]) & ms);
    }
    fd_ge_ref_add_affine_pipe( acc, acc+4, acc+8, acc+12, acc, acc+4, acc+8, acc+12, ent+4, ent, ent+8 );
  }
  for( int i=0; i<16; i++ ) r[i] = acc[i];
}

