static inline int fd_fe64_eq( const ulong a[4], const ulong b[4] ) {
  ulong ca[4], cb[4]; fd_fe64_canon( ca, a ); fd_fe64_canon( cb, b );
  return ((ca[0]^cb[0])|(ca[1]^cb[1])|(ca[2]^cb[2])|(ca[3]^cb[3]))==0UL;
}
