fd_ref_point_is_small_order_affine( const ulong a[16] ) {
  return fd_fe64_is_zero( a ) || fd_fe64_is_zero( a+4 ) || fd_fe64_eq( a+4, fd_ref_order8_y0 ) || fd_fe64_eq( a+4, fd_ref_order8_y1 );
}

