fd_ref_point_affine_canon( ulong cx[4], ulong cy[4], const ulong a[16] ) {
  ulong zi[4], ax[4], ay[4];
  fd_fe64_inv( zi, a+8 ); fd_fe64_mul_c( ax, a, zi ); fd_fe64_mul_c( ay, a+4, zi );
  fd_fe64_canon( cx, ax ); fd_fe64_canon( cy, ay );
}
